import unittest
from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

class FindGapsTests(unittest.TestCase):
    def setUp(self):
        self.opening = parse_span("09:00-17:00")

    def test_gap_between_two_shifts(self):
        worked = [
            parse_span("09:00-12:00"),
            parse_span("13:00-17:00")
        ]
        self.assertEqual(
            find_gaps(worked, self.opening),
            ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], self.opening),
            ["gap 09:00-17:00 (480 min)"]
        )

    def test_fully_covered_has_no_gaps(self):
        worked = [parse_span("09:00-17:00")]
        self.assertEqual(
            find_gaps(worked, self.opening), []
        )

    def test_gaps_at_both_ends(self):
        worked = [parse_span("10:00-11:00")]
        self.assertEqual(
            find_gaps(worked, self.opening),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 11:00-17:00 (360 min)"
            ]
        )

    def test_overlaps_and_touching_leave_no_false_gap(self):
        worked = [
            parse_span("09:00-11:00"),
            parse_span("10:30-12:00"),
            parse_span("12:00-12:30")
        ]
        self.assertEqual(
            find_gaps(worked, self.opening),
            ["gap 12:30-17:00 (270 min)"]
        )

    def test_span_matching_opening_hours_is_inside(self):
        worked = [parse_span("09:00-17:00")]
        self.assertEqual(
            find_gaps(worked, self.opening), []
        )

    def test_span_starting_before_opening_raises(self):
        worked = [parse_span("08:30-10:00")]
        with self.assertRaises(ValueError):
            find_gaps(worked, self.opening)

    def test_span_ending_after_opening_raises(self):
        worked = [parse_span("16:00-17:30")]
        with self.assertRaises(ValueError):
            find_gaps(worked, self.opening)
